// axes         → Line(-3..+3) black  + ConeGeometry(0.085,0.26) head at + end
// origin mass  → SphereGeometry(0.18) MeshPhong #7aa6dd + BackSide outline shell
// field shafts → InstancedMesh(CylinderGeometry(1,1,1,6)) per-instance color/scale
// field heads  → InstancedMesh(ConeGeometry(1,1,10))     per-instance color/scale
// sample arrow → Mesh cylinder + Mesh cone, #D94F00, thicker
// sample point → SphereGeometry(0.06) #D94F00
// guide line   → Line + LineDashedMaterial grey, origin → outward
// labels       → addLabel: x (bold italic), y, z, 0, and a |F| readout beside the sample point

/* ── lights (for the shaded origin sphere) ───────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dl = new THREE.DirectionalLight(0xffffff, 0.75);
dl.position.set(3, 5, 4);
scene.add(dl);

/* ── wireframe cube ──────────────────────────────────────────────────── */
const cube = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(4, 4, 4)),
  new THREE.LineBasicMaterial({ color: 0x35a1e8, transparent: true, opacity: 0.95 })
);
scene.add(cube);

/* ── axes ────────────────────────────────────────────────────────────── */
const black = new THREE.MeshBasicMaterial({ color: 0x000000 });
const blackLine = new THREE.LineBasicMaterial({ color: 0x000000 });
// world mapping: world X = figure y (right), world Z = figure x (lower-left), world Y = figure z (up)
const AXES = [
  { v: new THREE.Vector3(1, 0, 0) },   // figure y
  { v: new THREE.Vector3(0, 1, 0) },   // figure z
  { v: new THREE.Vector3(0, 0, 1) }    // figure x
];
AXES.forEach(({ v }) => {
  const g = new THREE.BufferGeometry().setFromPoints([
    v.clone().multiplyScalar(-3.05), v.clone().multiplyScalar(3)
  ]);
  scene.add(new THREE.Line(g, blackLine));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.26, 16), black);
  head.position.copy(v).multiplyScalar(3);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), v);
  scene.add(head);
});
// figure-x also shows an arrowhead at its visible lower-left end (world −Z)
{
  const v = new THREE.Vector3(0, 0, -1);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.26, 16), black);
  head.position.copy(v).multiplyScalar(3.05);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), v);
  scene.add(head);
}

/* ── origin point mass ───────────────────────────────────────────────── */
const massMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.18, 32, 24),
  new THREE.MeshPhongMaterial({ color: 0x7aa6dd, shininess: 70, specular: 0xdde9f8 })
);
scene.add(massMesh);
const outline = new THREE.Mesh(
  new THREE.SphereGeometry(0.197, 32, 24),
  new THREE.MeshBasicMaterial({ color: 0x3d6ca8, side: THREE.BackSide })
);
scene.add(outline);

/* ── field arrow data ────────────────────────────────────────────────── */
const GM = 1;
const ORANGE = new THREE.Color('#F26B21');
const TEAL = new THREE.Color('#1F8F8F');
const NAVY = new THREE.Color('#15335B');
const NEUTRAL = new THREE.Color('#2f9aa0');

// Perceptual length map: raw 1/r² collapses the outer shells to invisible
// specks, so map magnitude through a compressive power and keep a visible floor.
function lengthForRadius(r) {
  const F = GM / (r * r);
  return THREE.MathUtils.clamp(0.34 * Math.pow(F, 0.40), 0.175, 0.72);
}

const arrows = [];
function addArrowAt(p) {
  const r = p.length();
  if (r < 0.3) return;
